class Solution {
    public int reachNumber(int target) {
        target = Math.abs(target);
        int step = 0, sum = 0;
        while (sum < target || (sum - target) % 2 != 0) {
            step++;
            sum += step;
        }
        return step;
    }
}

class Solution {
    public int reachNumber(int target) {
        target = Math.abs(target);
        long lo = 1, hi = 2 * (long) Math.ceil(Math.sqrt(2.0 * target));
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            long sum = mid * (mid + 1) / 2;
            if (sum >= target) hi = mid;
            else lo = mid + 1;
        }
        long k = lo;
        long sum = k * (k + 1) / 2;
        while ((sum - target) % 2 != 0) {
            k++;
            sum += k;
        }
        return (int) k;
    }
}
